INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild`) VALUES
(40201, 0, 0, 0, 0, 0, 0, 0, 0, 'Yes, Malos and I have spoken on occasion. He has been studying the corruption of nature for some time now, and has even offered his assistance in understanding and, perhaps someday, reversing the corruption of my kind.$B$BHe is a good and kind soul, and if he needs my help, then I will do whatever is in my power.', 0),
(40202, 0, 0, 0, 0, 0, 0, 0, 0, 'I see. So it is as I feared. Broken free of my control, gnarled and enraged, it has been twisted beyond recognition by the undercurrent of corruption that plagues Teldrassil.', 0),
(40203, 0, 0, 0, 0, 0, 0, 0, 0, '<Malos contemplates the roots you hand him with great concern.>$B$BIt would appear that the roots are decayed, suggesting the treant was already deceased by the time you found it. What a horrible fate for a protector of the forests... No, for any of nature\'s creatures. I cannot begin to fathom how this could have happened.$B$BThis is a disturbing revelation indeed, and I am afraid that it has only created more questions. My research continues without the breakthrough we had hoped for, it seems. Nonetheless, you have done a great service to the forests and myself.$B$BPlease take one of these items as a token of my gratitude.', 0),
(40204, 0, 0, 0, 0, 0, 0, 0, 0, 'Have you come to aid in securing the Darnassus perimeter?$B$BThat is good to hear. We are in need of all the assistance available with my forces spread so thin. Recent events have strained our resources, as we now defend not only Ashenvale and Darkshore, but must have details all across our homes here in Teldrassil.', 0),
(40205, 0, 0, 0, 0, 0, 0, 0, 0, 'You have done a great service to the Kaldorei today, $N. Though I weep for the fate of our former allies, sorrow cannot give way to weakness. Elune guided your hand in defending our people\'s lands, and for carrying out her will, you are to be rewarded.', 0),
(40300, 0, 0, 0, 0, 0, 0, 0, 0, 'What is this? From a secret admirer?$B$BOh, silly Androl. He hasn\'t realized that I have known for years. I wish he would be more forward about his affections. Nonetheless, I thank you, $N. Please take this coin for your troubles.', 0),
(41788, 0, 0, 0, 0, 0, 0, 0, 0, 'So... Kyra has finally deigned to remember I exist? How endearing.$B$B<Drethanis regards you with a calm, unreadable gaze — no warmth, no gratitude.>$B$BVery well. If nothing else, your presence may serve a purpose. The rot runs deeper than any of us feared.', 0),
(41789, 0, 0, 0, 0, 0, 0, 0, 0, 'Their spirits now drift back to the Dream... to merge with Ursol, the Bear-God they worshipped with such fervor.$B$BHow ironic. For all their blind devotion, even Ursol could not shield them from corruption. Or perhaps... he chose not to.', 0),
(41790, 0, 0, 0, 0, 0, 0, 0, 0, 'So... it is done. A necessary task, and performed adequately.$B$B<He pauses, gaze drifting toward the tainted moonwell, voice lowering with unease.>$B$BAnd yet... a shadow lingers in my thoughts.$B$BWhat if Ursol himself has fallen? What if the silence is not from disdain, but from madness... corruption?$B$B<His tone grows cold, edged with quiet alarm.>$B$BA dangerous thought. One I dare not entertain lightly. The Archdruid must hear of this.$B$BYou have my thanks for your... assistance. May the winds carry you far from this cursed place.', 0),
(60111, 0, 0, 0, 0, 0, 0, 0, 0, 'Then it is done? It pains me greatly that it had come to this, but your actions today have ensured safe passage to Darnassus for our people.$B$BYour valor shall not go unrewarded, $C. Elune\'s blessing be upon you, always.', 0),
(60143, 0, 0, 0, 0, 0, 0, 0, 0, 'Oh, you\'ve found it! You have my eternal gratitude, $N!$B$BWill a well-tailored shirt suffice as compensation for your efforts? I keep a number of different colors in stock to suit any taste. Please, take your pick.$B$BIf a shirt is not to your liking, perhaps I could interest you in some raw material for your own purposes?', 0);
INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`, `VerifiedBuild`) VALUES
(40201, 0, 0, 'It is not often I have visitors. What can I assist you with?', 0),
(40202, 0, 0, 'You are back. Do you bring word from Tasala of my treant\'s whereabouts?', 0),
(40203, 0, 0, 'Have you found my treant? We cannot allow it to roam freely and wreak havoc in the forests.', 0),
(40205, 0, 0, 'Is it done, $N? We cannot afford to fail here, lest Darnassus itself be at risk.', 0),
(40300, 0, 0, 'Elune be with you, $C. What brings you to me?', 0),
(41788, 0, 0, 'Finally.', 0),
(41789, 0, 0, 'Time is of the essence — do not waste it.', 0),
(41790, 0, 0, 'Be wary, $C. He is a formidable enemy.', 0),
(60111, 0, 0, 'Agal and Greenpaw were once honorable and powerful allies. Now, in their madness, they pose a great threat to all who travel this road. There cannot be peace so long as they live, $C.', 0),
(60143, 0, 0, 'Have you found my sewing kit, $N?', 0);
